  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C02","C04","C10","C13","C14","C19","C27","C42","C43","C44","C45","C47","C52","C53"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01","C02","C04","C10","C13","C14","C43","C47"],
  "claims": [
    {
      "claim": "Human absolute oral bioavailability values for structurally related basic tertiary amines/amides are all above the 20% threshold: diphenhydramine 42–72%, dapoxetine 42%, trimipramine 41.4%, milnacipran 85%.",
      "card_ids": ["C01","C02","C04","C10","C13","C14","C19","C27"]
    },
    {
      "claim": "L4 provides supportive absorption evidence: loperamide, a structurally similar diphenylamide tertiary amine with three phenyls and a basic amine, shows high Caco-2 Papp A-B (17.0×10^-6 cm/s) and an efflux ratio of 0.8; cetirizine is reported as high human intestinal absorption; ketoprofen Caco-2 Papp values are high (4.2–6.0×10^-5 cm/s).",
      "card_ids": ["C42","C43","C44","C45","C47","C52","C53"]
    },
    {
      "claim": "The fexofenadine solubility records (5.4–11.3 mg/mL) are measured only in water containing 10–30% w/v Gelucire 44/14 and are formulation-specific; they do not provide intrinsic solubility or F evidence for the query.",
      "card_ids": ["C46","C48","C49","C50","C51"]
    },
    {
      "claim": "No L4 record is a direct absolute oral bioavailability measurement for the query; the only low-F records in the full evidence set are species-specific animal values (diphenhydramine in dogs, ampicillin in fasted calves) and are not transferable affirmative evidence for F<20%.",
      "card_ids": ["C23","C24"]
    },
    {
      "claim": "L3 oral AUC/Cmax records lack IV comparators and do not quantify F; they do not alter the prediction.",
      "card_ids": ["C30","C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C42","C43","C44","C45","C47","C52","C53"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No human F data for an exact structural analog; the closest L4 analog (loperamide) provides only Caco-2 permeability, not systemic F.",
    "No intrinsic solubility/dissolution data for the query; L4 fexofenadine solubility values are formulation-specific (Gelucire 44/14).",
    "No P-gp/efflux or first-pass metabolism data for the query; C43 efflux ratio is for loperamide in Caco-2, not the query.",
    "The query's low neutral fraction and high logP leave uncertainty about solubility and dissolution, but this is not affirmative evidence for F<20%."
  ],
  "decision_summary": "L4 intestinal permeability/absorption records, especially the structurally similar loperamide Caco-2 high-permeability/low-efflux record and cetirizine high intestinal absorption, support a favorable absorption component. Fexofenadine solubility records are formulation-specific and not applicable. No direct F measurement for the query appears, and no affirmative threshold-relevant evidence for F<20% is present. Prediction remains high; confidence moderate; evidence basis strengthened."
}

